    [p.hip, p.chest, p.head].every(point) &&
    [p.feet, p.hands, p.knees, p.elbows].every(
      (v) => Array.isArray(v) && v.length === 2 && v.every(point),
    ) &&
    Array.isArray(p.footAngles) &&
    p.footAngles.length === 2 &&
    p.footAngles.every(Number.isFinite)
