    // made the folded leg rotate almost 180 degrees between adjacent frames.
    p.feet[s][1] = Math.min(
      p.feet[s][1],
      p.hip[1] - 0.245,
      p.hip[1] - 0.345 + 0.8 * Math.abs(p.feet[s][0] - p.hip[0]),
    );
