  const rotate = (v: Point): Point => [
    v[0] * Math.cos(angle) - (v[1] - 0.85) * Math.sin(angle),
    0.85 + v[0] * Math.sin(angle) + (v[1] - 0.85) * Math.cos(angle),
    v[2],
  ];
