    pose[key] = rotate(pose[key]);
  for (const key of ["feet", "hands", "knees", "elbows"] as const)
    pose[key] = pose[key].map(rotate);
  pose.footAngles = pose.footAngles.map((a) => a + angle);
  return pose;
